insert into public.guide_entries (slug, category, title, summary, objective, do_items, avoid_items, steps, source, published, sort) values
  ('hidratacion-diaria', 'hidratacion', 'Agua durante el día', 'Cómo repartir el agua sin acordarte a la fuerza.', 'Mantener una hidratación suficiente con agua simple, sin depender de bebidas azucaradas.', array['Lleva una botella de agua contigo', 'Toma un vaso al despertar y uno antes de cada comida']::text[], array['Reemplazar el agua por gaseosas o jugos envasados', 'Esperar a tener sed para tomar agua']::text[], array['Llena una botella de 1 litro cada mañana', 'Bebe una porción al terminar cada comida principal', 'Revisa al final del día cuántos vasos tomaste']::text[], 'OMS: Dieta saludable (nota descriptiva)', true, 10),
  ('hidratacion-ejercicio', 'hidratacion', 'Hidratarse al hacer ejercicio', 'Qué tomar antes, durante y después de moverte.', 'Evitar la deshidratación en caminatas, trote y fuerza.', array['Toma medio vaso de agua 30 minutos antes', 'Repón líquidos después de sudar']::text[], array['Tomar mucha agua de golpe justo antes de entrenar', 'Usar bebidas energéticas como agua de todos los días']::text[], array['Antes: medio vaso de agua', 'Durante: sorbos cada 15 o 20 minutos en sesiones largas', 'Después: un vaso de agua y una fruta si entrenaste más de 45 minutos']::text[], 'OMS: Dieta saludable (nota descriptiva)', true, 20),
  ('porciones-plato', 'porciones', 'Cómo armar el plato', 'Un plato criollo equilibrado con medidas de la casa.', 'Repartir el plato entre verduras, proteína y carbohidratos sin pesar la comida.', array['Mitad del plato con verduras o ensalada', 'Un cuarto con proteína (pollo, pescado, huevo, menestra)', 'Un cuarto con arroz, papa, yuca o choclo']::text[], array['Servirte directamente de la olla sin medir', 'Comer el arroz con fritada o frituras todos los días']::text[], array['Usa un plato mediano en vez de uno grande', 'Sirve primero las verduras', 'Completa con la proteína y luego el carbohidrato']::text[], 'Guías Alimentarias Basadas en Alimentos del Ecuador (MSP)', true, 30),
  ('porciones-medidas-caseras', 'porciones', 'Medidas caseras', 'Tazas, puños y palmas para estimar porciones.', 'Estimar porciones sin balanza, con medidas que todos tienen en casa.', array['Una palma de mano como referencia para la carne o el pescado', 'Un puño cerrado como referencia para arroz, papa o fruta']::text[], array['Servir a ojo un plato lleno de arroz', 'Contar como una porción un paquete entero de galletas']::text[], array['Mide tu palma y tu puño una vez con una taza medidora', 'Usa esas medidas durante una semana', 'Ajusta según cómo te sientas y lo que te indique tu nutricionista']::text[], 'Guías Alimentarias Basadas en Alimentos del Ecuador (MSP)', true, 40),
  ('antes-de-entrenar', 'antes_entrenar', 'Comer antes de entrenar', 'Una comida ligera 1 o 2 horas antes de moverte.', 'Llegar con energía sin sentir pesadez durante la sesión.', array['Elige carbohidratos sencillos como fruta o pan integral', 'Añade un poco de proteína como huevo o queso fresco']::text[], array['Comer frituras o platos muy grasos justo antes', 'Entrenar en ayunas si te sientes mareado']::text[], array['Come 1 o 2 horas antes', 'Opciones: banano con avena, o pan integral con huevo', 'Si tienes poco tiempo, una fruta 30 minutos antes']::text[], 'OMS: Actividad física (nota descriptiva)', true, 50),
  ('despues-de-entrenar', 'despues_entrenar', 'Recuperarte después de entrenar', 'Qué comer tras la sesión para recuperar músculo.', 'Reponer energía y apoyar la recuperación muscular.', array['Come una porción de proteína dentro de las 2 horas siguientes', 'Incluye fruta o verduras en esa comida']::text[], array['Saltarte la comida después de entrenar', 'Premiarte con bebidas azucaradas']::text[], array['Después de entrenar, bebe agua', 'Come proteína (pollo, pescado, huevo o menestra)', 'Completa el plato con verduras y un carbohidrato sencillo']::text[], 'OMS: Actividad física (nota descriptiva)', true, 60),
  ('comer-fuera-almuerzo', 'comer_fuera', 'Almorzar fuera de casa', 'Cómo elegir en un restaurante sin salirte del plan.', 'Elegir platos con más verdura y menos fritura cuando comes fuera.', array['Pide sopa, caldo o encebollado sin chifles extra', 'Pide la ensalada o las verduras como acompañamiento']::text[], array['Pedir un plato frito y una gaseosa grande', 'Comer todo el arroz y el pan que te traen primero']::text[], array['Revisa el menú antes de llegar', 'Pide la porción que sueles comer en casa', 'Si te sirven de más, guarda la mitad para otro día']::text[], 'Guías Alimentarias Basadas en Alimentos del Ecuador (MSP)', true, 70),
  ('comer-fuera-cena', 'comer_fuera', 'Cenar en familia o con amigos', 'Disfrutar la reunión sin descarrilar la semana.', 'Disfrutar la comida compartida con decisiones sencillas.', array['Empieza por la ensalada o la sopa', 'Comparte el plato fuerte si es muy abundante']::text[], array['Repetir porciones solo porque están en la mesa', 'Compensar saltándote la comida del día siguiente']::text[], array['Come despacio y deja de comer cuando estés satisfecho', 'Elige agua o una bebida sin azúcar', 'Al día siguiente vuelve a tu horario normal']::text[], 'OMS: Dieta saludable (nota descriptiva)', true, 80),
  ('descanso-sueno', 'descanso', 'Dormir mejor', 'Hábitos simples para dormir entre 7 y 8 horas.', 'Dormir lo suficiente para recuperarte y tener hambre regular.', array['Acuéstate y levántate a la misma hora', 'Deja el celular fuera del dormitorio']::text[], array['Cenar muy tarde o muy pesado', 'Tomar café después de las 3 de la tarde']::text[], array['Fija una hora de dormir', 'Baja la luz 30 minutos antes', 'Si no puedes dormir en 20 minutos, levántate y haz algo tranquilo']::text[], 'OMS: Actividad física (nota descriptiva)', true, 90),
  ('descanso-dias-de-pausa', 'descanso', 'Días de descanso', 'Por qué también necesitas días sin entrenar.', 'Dejar que el cuerpo se recupere para avanzar sin lesiones.', array['Haz al menos un día de descanso a la semana', 'Camina suave si te apetece']::text[], array['Entrenar fuerte todos los días', 'Ignorar dolor articular o cansancio extremo']::text[], array['Elige un día fijo de descanso', 'En ese día haz solo estiramientos o una caminata suave', 'Si sientes dolor persistente, consulta con tu nutricionista']::text[], 'OMS: Actividad física (nota descriptiva)', true, 100),
  ('compras-lista', 'compras', 'Hacer la lista del mercado', 'Comprar lo necesario para toda la semana.', 'Llevar al mercado lo que vas a cocinar y evitar compras impulsivas.', array['Planifica las comidas de tres a cinco días', 'Compra verduras de temporada y pescado fresco']::text[], array['Ir al mercado con hambre', 'Comprar embutidos y snacks empacados por costumbre']::text[], array['Revisa qué te queda en casa', 'Escribe la lista por secciones: verduras, proteínas, granos', 'Compra según la lista y revisa las etiquetas de sal y azúcar']::text[], 'Guías Alimentarias Basadas en Alimentos del Ecuador (MSP)', true, 110),
  ('compras-etiquetas', 'compras', 'Leer las etiquetas', 'Qué mirar en un producto empacado.', 'Escoger productos empacados con menos azúcar, sal y grasa.', array['Compara el sodio por porción entre marcas', 'Prefiere productos con pocos ingredientes que reconozcas']::text[], array['Fiarte solo de la frase «light» o «natural»', 'Comprar bebidas azucaradas como si fueran jugo natural']::text[], array['Mira el tamaño de la porción', 'Revisa azúcares y sodio por porción', 'Elige el producto con menos de ambos cuando tengas opciones']::text[], 'OMS: Dieta saludable (nota descriptiva)', true, 120)
